package com.manageinvoice.categories;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.manageinvoice.tenancy.WorkspaceService;
@Service public class CategoryService { private final CategoryRepository categories; private final WorkspaceService workspaces; public CategoryService(CategoryRepository categories,WorkspaceService workspaces){this.categories=categories;this.workspaces=workspaces;} public List<Category> list(UUID workspaceId,UUID userId){workspaces.requireMembership(workspaceId,userId);return categories.findByWorkspaceIdAndActiveTrue(workspaceId);} @Transactional public Category create(UUID workspaceId,UUID userId,CreateRequest request){workspaces.requireMembership(workspaceId,userId);Category category=new Category();category.setWorkspaceId(workspaceId);category.setName(request.name().trim());category.setDescription(request.description());category.setColor(request.color());return categories.save(category);} @Transactional public Category update(UUID workspaceId,UUID userId,UUID categoryId,CreateRequest request){workspaces.requireMembership(workspaceId,userId);Category category=categories.findByWorkspaceIdAndId(workspaceId,categoryId).orElseThrow();category.setName(request.name().trim());category.setDescription(request.description());category.setColor(request.color());return categories.save(category);} public void archive(UUID workspaceId,UUID userId,UUID categoryId){workspaces.requireMembership(workspaceId,userId);Category category=categories.findByWorkspaceIdAndId(workspaceId,categoryId).orElseThrow();category.setActive(false);categories.save(category);} public record CreateRequest(String name,String description,String color){} }
